const query = $('Webhook').first().json.query;
const managerId = parseInt(query.manager_id);

if (!managerId) {
  throw new Error('Missing required parameter: manager_id');
}

return { json: { manager_id: managerId } };

const managerInfo = $input.first().json;
const inputData = $('Validate Input').first().json;

// Проверяем, что у менеджера есть подчинённые-менеджеры
if (!managerInfo.has_manager_subordinates && managerInfo.role !== 'c_level' && managerInfo.role !== 'admin') {
  throw new Error('Access denied: You must have manager subordinates to access this feature');
}

return { json: inputData };

const rows = $input.all();

return {
  json: {
    success: true,
    data: rows.map(r => r.json)
  }
};
